import{_ as t}from"./chunks/69293419e8ab61a31bf9a2c7fd7f16e7.ZWdXfrQD.js";import{_ as r}from"./chunks/738d0579756a290c0d82f05c51362540.BIcfcH-U.js";import{_ as a}from"./chunks/1e22359c4d5983a08a364d2c711ab776.BH8a6X41.js";import{_ as n,c as l,a2 as e,o as s}from"./chunks/framework.BnrAgU0Y.js";const g="/bllm/assets/9f93d0c8e5e9eea1bc613f84414826ce.C0_udDmb.png",i="/bllm/assets/c742f5c17fb479e002c6c0fc4978f2c3.CcgVpKu6.png",p="/bllm/assets/cce0be1ce317b56cce245ef98ed56b5d.C-hsYwr4.png",c="/bllm/assets/4f46ffb239c47e375346af5ee9f01184.CmvFyYNF.png",q=JSON.parse('{"title":"Langflow 概述","description":"Langflow 概述","frontmatter":{"title":"Langflow 概述","description":"Langflow 概述","layout":"doc"},"headers":[],"relativePath":"langflow/concepts-overview.md","filePath":"langflow/concepts-overview.md"}'),d={name:"langflow/concepts-overview.md"};function h(f,o,m,u,w,b){return s(),l("div",null,o[0]||(o[0]=[e('<h1 id="langflow-概述" tabindex="-1">Langflow 概述 <a class="header-anchor" href="#langflow-概述" aria-label="Permalink to &quot;Langflow 概述&quot;">​</a></h1><p>本页面探讨了 Langflow 的基础构建模块，从问题 <strong>“什么是 flow?”</strong> 开始。</p><h2 id="什么是流程" tabindex="-1">什么是流程？ <a class="header-anchor" href="#什么是流程" aria-label="Permalink to &quot;什么是流程？&quot;">​</a></h2><p><strong>流程</strong> 是一种应用程序。它接收输入，进行处理，并生成输出。</p><p>流程是在 <strong>工作区</strong> 中创建的，通过从组件侧边栏拖拽组件来完成。</p><p><img src="'+g+'" alt="Basic prompting flow within in the workspace"></p><p>一个流程可以像<a href="/get-started-quickstart">基础提示流程</a>一样简单，该流程创建一个包含四个组件的 OpenAI 聊天机器人。</p><ul><li>流程中的每个组件都是一个<strong>节点</strong>，执行特定任务，如 AI 模型或数据源。</li><li>每个组件都有一个<strong>配置</strong>菜单。点击<strong>代码</strong>面板可以查看组件的底层 Python 代码。</li><li>组件通过<strong>边</strong>连接，形成流程。</li></ul><p>如果你熟悉 <a href="https://reactflow.dev/learn" target="_blank" rel="noopener noreferrer">ReactFlow</a>，一个**流程**就是基于节点的应用程序，一个**组件**是一个节点，组件之间的连接为**边**。</p><p>当运行一个流程时，Langflow 从节点（组件）和边（组件之间的连接）构建一个有向无环图（DAG）对象，节点按顺序排序以确定执行顺序。图的构建调用各个组件的 `def_build` 函数来验证和准备节点。然后以依赖顺序处理该图。每个节点被构建并顺序执行，构建节点的结果被传递给依赖前一个节点结果的其他节点。</p><p>流程存储在本地磁盘上的默认位置：</p><ul><li><strong>Linux 或 Windows 上的 WSL</strong>：<code>home/&lt;用户名&gt;/.cache/langflow/</code></li><li><strong>MacOS</strong>：<code>/Users/&lt;用户名&gt;/Library/Caches/langflow/</code></li></ul><p>可以通过 <a href="/environment-variables#LANGFLOW_CONFIG_DIR">LANGFLOW_CONFIG_DIR</a> 环境变量自定义流程存储位置。</p><h2 id="找到你的方向" tabindex="-1">找到你的方向 <a class="header-anchor" href="#找到你的方向" aria-label="Permalink to &quot;找到你的方向&quot;">​</a></h2><p>如果你是 Langflow 的新手，刚开始时感到有点迷茫是正常的。我们会带你参观一下，这样你可以快速熟悉并开始创建应用程序。</p><p>Langflow 有四个不同的区域：<code>工作区</code> 是构建流程的主要区域。组件侧边栏位于左侧，列出了可用的<code>组件</code>。<code>游乐场</code>和<code>API 面板</code>位于右上角。</p><p><img src="'+i+'" alt=""></p><h2 id="工作区" tabindex="-1">工作区 <a class="header-anchor" href="#工作区" aria-label="Permalink to &quot;工作区&quot;">​</a></h2><p><strong>工作区</strong>是您通过在流程中连接和运行组件来创建 AI 应用程序的地方。</p><p>工作区控件允许您调整视图并锁定流程位置。</p><ul><li>使用 <strong>添加备注</strong> 按钮向流程添加 <strong>备注</strong>，类似于代码中的注释。</li><li>要访问<a href="#settings">设置</a>菜单，请点击 <img src="https://www.w3.org/2000/svg" alt="齿轮图标"> <strong>设置</strong>。</li></ul><p>此菜单包含 <strong>全局变量</strong>、<strong>Langflow API</strong>、<strong>快捷键</strong> 和 <strong>消息</strong> 的配置选项。</p><h2 id="组件" tabindex="-1">组件 <a class="header-anchor" href="#组件" aria-label="Permalink to &quot;组件&quot;">​</a></h2><p>一个<strong>组件</strong>是流程中的一个单独构建块，由定义其功能的输入、输出和参数组成。</p><p>要将一个组件添加到您的流程中，请将其从侧边栏拖动到工作区。</p><p>要连接组件，请从一个组件的输出句柄 (⚪) 拖动一条线到另一个组件的输入句柄。</p><p>欲了解更多信息，请参阅 <a href="/bllm/concepts-components.html">组件概述</a>。</p><p><img src="'+t+'" alt="Prompt component"></p><h2 id="playground" tabindex="-1">Playground <a class="header-anchor" href="#playground" aria-label="Permalink to &quot;Playground&quot;">​</a></h2><p><strong>Playground</strong> 执行工作区中的当前流程。</p><p>与您的流程聊天，查看输入和输出，并修改您的 AI 记忆以实时调整响应。</p><p>在 <strong>Playground</strong> 中可以打开并实时测试 <strong>Chat Input</strong>（聊天输入）或 <strong>Chat Output</strong>（聊天输出）组件。</p><p>更多信息，请参见 <a href="/bllm/concepts-playground.html">Playground</a>。</p><p><img src="'+r+'" alt=""></p><h2 id="api-面板" tabindex="-1">API 面板 <a class="header-anchor" href="#api-面板" aria-label="Permalink to &quot;API 面板&quot;">​</a></h2><p>API 面板提供了将您的流程集成到外部应用程序中的代码模板。</p><p>有关更多信息，请参阅 <a href="/bllm/concepts-api.html">API 面板</a>。</p><p><img src="'+a+'" alt=""></p><h2 id="查看日志" tabindex="-1">查看日志 <a class="header-anchor" href="#查看日志" aria-label="Permalink to &quot;查看日志&quot;">​</a></h2><p><strong>日志</strong>面板提供了工作区内所有组件执行的详细记录。</p><p>要访问<strong>日志</strong>面板，请点击您的<strong>流程名称</strong>，然后选择<strong>日志</strong>。</p><p><img src="'+p+'" alt=""></p><p>Langflow 将日志存储在由环境变量 <code>LANGFLOW_CONFIG_DIR</code> 指定的位置。这个目录的默认位置取决于您的操作系统。</p><ul><li><strong>Linux/WSL</strong>: <code>~/.cache/langflow/</code></li><li><strong>macOS</strong>: <code>/Users/&lt;用户名&gt;/Library/Caches/langflow/</code></li><li><strong>Windows</strong>: <code>%LOCALAPPDATA%\\langflow\\langflow\\Cache</code></li></ul><p>要修改日志文件的位置：</p><ol><li>在您的 <code>.env</code> 文件中添加 <code>LANGFLOW_LOG_FILE=path/to/logfile.log</code>。</li><li>要使用 <code>.env</code> 文件中的值启动 Langflow，请使用 <code>uv run langflow run --env-file .env</code> 启动 Langflow。</li></ol><p>您可以在<a href="https://github.com/langflow-ai/langflow/blob/main/.env.example" target="_blank" rel="noreferrer">项目仓库</a>中找到一个示例 <code>.env</code> 文件。</p><h2 id="项目和文件夹" tabindex="-1">项目和文件夹 <a class="header-anchor" href="#项目和文件夹" aria-label="Permalink to &quot;项目和文件夹&quot;">​</a></h2><p><strong>我的项目</strong>页面显示您在 Langflow 工作区中创建的所有流和组件。</p><p><img src="'+c+'" alt=""></p><p><strong>我的项目</strong>是默认的文件夹，所有新的项目和组件最初都存储在这里。</p><p>项目、文件夹和流程以 JSON 对象的形式进行交换。</p><ul><li>要创建新文件夹，点击 📁 <strong>新建文件夹</strong>。</li><li>要重命名文件夹，双击文件夹名称。</li><li>要下载文件夹，点击 📥 <strong>下载</strong>。</li><li>要上传文件夹，点击 📤 <strong>上传</strong>。默认的最大文件上传大小为 100 MB。</li><li>要移动流程或组件，将其拖放到所需的文件夹。</li></ul><h2 id="选项菜单" tabindex="-1">选项菜单 <a class="header-anchor" href="#选项菜单" aria-label="Permalink to &quot;选项菜单&quot;">​</a></h2><p>在 Langflow 工作区中，标有项目名称的下拉菜单提供了用于当前流程的管理和自定义选项。</p><ul><li><strong>新建</strong>: 从头开始创建一个新的流程。</li><li><strong>设置</strong>: 调整当前流程的特定设置，例如其名称、描述和终端名称。</li><li><strong>日志</strong>: 查看当前项目的日志，包括执行历史、错误和其他运行时事件。</li><li><strong>导入</strong>: 从 JSON 文件中导入一个流程或组件到工作区。</li><li><strong>导出</strong>: 将当前流程导出为 JSON 文件。</li><li><strong>撤销 (⌘Z)</strong>: 撤销项目中的最后一个操作。</li><li><strong>重做 (⌘Y)</strong>: 重新应用之前撤销的操作。</li><li><strong>刷新所有</strong>: 刷新所有组件并删除缓存。</li></ul><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h2><p>点击 <img src="https://www.svgrepo.com/show/2046/settings.svg" alt="Gear icon"> <strong>设置</strong> 以访问<strong>全局变量</strong>、<strong>Langflow API</strong>、<strong>快捷键</strong>和<strong>消息</strong>。</p>',58)]))}const A=n(d,[["render",h]]);export{q as __pageData,A as default};
